#include "morok/model/learn/g1_checkpoint.hpp"
#include "morok/model/parameters/g1_parameters.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace morok::model;void require(bool x,const char*m){if(!x)throw std::runtime_error(m);}
int main(){try{auto path=std::filesystem::temp_directory_path()/"morok-g1-checkpoint-test.ckpt";G1Checkpoint c;initialize_g1_parameters(c.parameters,123);c.has_optimizer=true;c.optimizer=G1AdamWState{};auto&s=std::get<G1AdamWState>(c.optimizer);s.step=17;s.first_moment[4]=.25F;s.second_moment[4]=.5F;c.has_rng=true;c.rng_state={1,2,3,4};c.epoch=9;c.block_index=1234;c.document_order={4,2,8};c.document_position=3;c.metadata="corpus_hash=abc\nseed=42";save_g1_checkpoint(path,c);auto d=load_g1_checkpoint(path);require(d.parameters.flatten()==c.parameters.flatten(),"parameters roundtrip");require(d.has_optimizer&&std::get<G1AdamWState>(d.optimizer).step==17,"AdamW step");require(std::get<G1AdamWState>(d.optimizer).first_moment[4]==.25F,"AdamW moments");require(d.has_rng&&d.rng_state==c.rng_state,"RNG");require(d.epoch==9&&d.block_index==1234,"counters");require(d.document_order==c.document_order&&d.document_position==3,"cursor");require(d.metadata==c.metadata,"metadata");{std::fstream f(path,std::ios::binary|std::ios::in|std::ios::out);f.seekp(-1,std::ios::end);char x='X';f.write(&x,1);}bool rejected=false;try{(void)load_g1_checkpoint(path);}catch(const std::runtime_error&){rejected=true;}require(rejected,"CRC corruption rejected");G1Checkpoint inf;inf.parameters=c.parameters;save_g1_checkpoint(path,inf);auto q=load_g1_checkpoint(path);require(!q.has_optimizer&&!q.has_rng,"inference checkpoint");G1Checkpoint sg;sg.parameters=c.parameters;sg.has_optimizer=true;sg.optimizer=G1SGDMomentumState{};std::get<G1SGDMomentumState>(sg.optimizer).step=3;save_g1_checkpoint(path,sg);auto z=load_g1_checkpoint(path);require(std::holds_alternative<G1SGDMomentumState>(z.optimizer)&&std::get<G1SGDMomentumState>(z.optimizer).step==3,"SGD checkpoint");std::filesystem::remove(path);std::cout<<"G1 checkpoint tests passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}